<template><el-dialog title="导入账号信息" :visible.sync="visible" width="680px"><p>支持 Excel 或 CSV。固定列：用户名、密码、备注、服务器槽位、首次完善资料；其他列自动作为自定义字段。</p><input ref="picker" type="file" accept=".xlsx,.xls,.csv" @change="read"><el-table v-if="rows.length" :data="rows.slice(0,8)" size="small"><el-table-column v-for="name in columns" :key="name" :prop="name" :label="name"/></el-table><span slot="footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!rows.length" @click="submit">导入 {{rows.length}} 个账号</el-button></span></el-dialog></template>
<script>import * as XLSX from 'xlsx';import {createAccount} from '@/api/AccountManagement';export default{props:{slots:{type:Array,default:()=>[]}},data:()=>({visible:false,saving:false,rows:[],columns:[]}),methods:{open(){this.rows=[];this.columns=[];this.visible=true},read(e){const file=e.target.files&&e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=event=>{const book=XLSX.read(event.target.result,{type:'array'});this.rows=XLSX.utils.sheet_to_json(book.Sheets[book.SheetNames[0]],{defval:''});this.columns=this.rows.length?Object.keys(this.rows[0]):[]};reader.readAsArrayBuffer(file)},slotId(value){const text=String(value||'');const match=this.slots.find(s=>s.slotId===text||`${s.agentId} / 槽位 ${s.slotNumber}`===text);return match&&match.slotId},async submit(){this.saving=true;try{for(const row of this.rows){const custom={};Object.keys(row).filter(k=>!['用户名','密码','备注','服务器槽位','首次完善资料'].includes(k)).forEach(k=>custom[k]=String(row[k]||''));await createAccount({userName:String(row.用户名||''),password:String(row.密码||''),remark:String(row.备注||''),slotId:this.slotId(row.服务器槽位),requireProfile:['是','1','true'].includes(String(row.首次完善资料).toLowerCase()),enabled:true,customFields:custom})}this.visible=false;this.$emit('done');this.$message.success('账号导入完成')}finally{this.saving=false}}}}</script>
